.libPaths(c(path.expand('~/Library/R/arm64/4.5/library'),.libPaths()))
source('R/trim_bootstrap_preview.R');source('R/trim_release_runtime.R')
root<-tempfile('integral-release-');dir.create(root)
html<-file.path(root,'bootstrap.html');writeLines('<p>diagnostisch</p>',html)
meta<-list(schema='trim-bootstrap-presentation-v1',publication_status='diagnostisch',source_hash=paste(rep('a',64),collapse=''),year_from=1958L,year_to=2025L,html_sha256=digest::digest(file=html,algo='sha256'))
jsonlite::write_json(meta,file.path(root,'manifest.json'),auto_unbox=TRUE)
r<-list(schema='meijendel-integral-release-v1',release_id='test-A',mode='local_rehearsal',presentation_approved=TRUE,year_from=1958L,year_to=2025L,source_hash=meta$source_hash,bootstrap=list(root='.',html_sha256=meta$html_sha256,manifest_sha256=digest::digest(file=file.path(root,'manifest.json'),algo='sha256')))
control<-file.path(root,'release.json');jsonlite::write_json(r,control,auto_unbox=TRUE)
Sys.setenv(MEIJENDEL_BOOTSTRAP_RELEASE='1',MEIJENDEL_RELEASE_MANIFEST=control,MEIJENDEL_BIND_HOST='127.0.0.1')
stopifnot(!is.null(load_trim_bootstrap_preview()))
r$year_to<-2026L;jsonlite::write_json(r,control,auto_unbox=TRUE);stopifnot(is.null(load_trim_bootstrap_preview()))
Sys.unsetenv('MEIJENDEL_ALLOW_HISTORICAL_REHEARSAL');stopifnot(inherits(try(load_historical_release_cache('absent'),silent=TRUE),'try-error'))
Sys.setenv(MEIJENDEL_ALLOW_HISTORICAL_REHEARSAL='1');stopifnot(inherits(try(load_historical_release_cache('absent'),silent=TRUE),'try-error'))
cat('Actieve release, verkeerde jaargrens en historische-cacheguard: OK\n')
